class Solution(object):
    def subdomainVisits(self, cpdomains):
        """
        :type cpdomains: List[str]
        :rtype: List[str]
        """
        d = collections.defaultdict(int)
        for c in cpdomains:
            freq, domain = c.split()
            t = domain.split(".")
            cur = ""
            for i in range(len(t) - 1, -1, -1):
                if cur:
                    cur = t[i] + "." + cur
                else:
                    cur = t[i]
                d[cur] += int(freq)
        ans = []
        for k, v in d.items():
            ans.append(str(v) + " " + k)
        return ans
